async function openInvoiceModal() {
    editingInvoiceId = null;
    const co = await fetchDropdown('/customers');
    openModal('New Invoice', `<div><label class="block text-sm mb-1">Customer *</label><select id="i_customerId" required class="dark-input"><option value="">Select</option>${co}</select></div><div><label class="block text-sm mb-1">Due Date *</label><input type="date" id="i_dueDate" required class="dark-input"></div><div><label class="block text-sm mb-1">Status</label><select id="i_status" class="dark-input"><option>DRAFT</option><option>SENT</option><option>PAID</option></select></div><div><label class="block text-sm mb-1">Notes</label><textarea id="i_notes" class="dark-input"></textarea></div><hr><div><div class="flex justify-between mb-2"><h4 class="text-sm font-medium">Line Items</h4><button type="button" onclick="addInvoiceLineItem()" class="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded">+ Add</button></div><div id="invoice-items-container" class="space-y-2"></div></div><div class="mt-4 space-y-1 text-sm"><div class="flex justify-between"><span>Subtotal:</span><span id="inv_subtotal">AED 0.00</span></div><div class="flex justify-between"><span>VAT:</span><span id="inv_vat">AED 0.00</span></div><div class="flex justify-between font-bold border-t pt-1"><span>Total:</span><span id="inv_grand_total">AED 0.00</span></div></div>`);
    const mb = document.querySelector('#modal > div'); mb.classList.remove('max-w-md'); mb.classList.add('max-w-2xl');
    let dd = new Date(); dd.setDate(dd.getDate() + 15); document.getElementById('i_dueDate').valueAsDate = dd;
    addInvoiceLineItem();
    modalForm.onsubmit = (e) => { e.preventDefault(); const items = collectInvoiceLineItems(); if (!items.length) { alert('Add at least 1 item.'); return; } const sub = items.reduce((s,i)=>s+(i.qty*i.unitPrice),0), vat = items.reduce((s,i)=>s+i.vatAmount,0), tot = sub+vat; apiFetch('/invoices','POST',{customerId:getInput('i_customerId'),dueDate:getInput('i_dueDate'),subtotal:sub,vatAmount:vat,total:tot,status:getInput('i_status'),notes:getInput('i_notes'),lineItems:items}).then(()=>{closeModal();alert('Invoice created!');fetchAndRenderInvoices();}).catch(err=>{document.getElementById('modal-error').innerText=err.message;document.getElementById('modal-error').classList.remove('hidden');}); };
}

function addInvoiceLineItem(desc, qty, price, vatRate) { const c = document.getElementById('invoice-items-container'); c.insertAdjacentHTML('beforeend', `<div class="inv-line-item grid grid-cols-12 gap-2 items-center p-2 bg-gray-50 rounded"><input type="text" placeholder="Description" class="li-desc col-span-4 dark-input" value="${desc||''}"><input type="number" placeholder="Qty" step="0.01" class="li-qty col-span-2 dark-input" value="${qty||1}" oninput="calcInvoiceTotals()"><input type="number" placeholder="Price" step="0.01" class="li-price col-span-2 dark-input" value="${price||0}" oninput="calcInvoiceTotals()"><input type="number" placeholder="VAT%" step="0.01" class="li-vat col-span-1 dark-input" value="${vatRate||5}" oninput="calcInvoiceTotals()"><span class="li-vat-amt col-span-2 text-right text-sm">AED 0.00</span><button type="button" onclick="this.parentElement.remove();calcInvoiceTotals();" class="col-span-1 text-red-500">X</button></div>`); calcInvoiceTotals(); }
function collectInvoiceLineItems() { const items = []; document.querySelectorAll('.inv-line-item').forEach(row => { const desc = row.querySelector('.li-desc').value; if (desc) { const qty = parseFloat(row.querySelector('.li-qty').value)||0, price = parseFloat(row.querySelector('.li-price').value)||0, vatRate = parseFloat(row.querySelector('.li-vat').value)||0, exclVAT = qty*price, vatAmount = exclVAT*(vatRate/100); items.push({description:desc,quantity:qty,unitPrice:price,vatRate,exclVAT,vatAmount,inclVAT:exclVAT+vatAmount}); } }); return items; }
function calcInvoiceTotals() { let sub=0,vatT=0; document.querySelectorAll('.inv-line-item').forEach(row => { const qty=parseFloat(row.querySelector('.li-qty').value)||0, price=parseFloat(row.querySelector('.li-price').value)||0, vatRate=parseFloat(row.querySelector('.li-vat').value)||0, exclVAT=qty*price, vatAmount=exclVAT*(vatRate/100); row.querySelector('.li-vat-amt').innerText=`AED ${vatAmount.toFixed(2)}`; sub+=exclVAT; vatT+=vatAmount; }); document.getElementById('inv_subtotal').innerText=`AED ${sub.toFixed(2)}`; document.getElementById('inv_vat').innerText=`AED ${vatT.toFixed(2)}`; document.getElementById('inv_grand_total').innerText=`AED ${(sub+vatT).toFixed(2)}`; }

async function editInvoice(id) { try { const inv = await apiFetch(`/invoices/${id}`); editingInvoiceId = id; const co = await fetchDropdown('/customers'); openModal('Edit Invoice', `<div><label class="block text-sm mb-1">Customer *</label><select id="i_customerId" required class="dark-input"><option value="">Select</option>${co}</select></div><div><label class="block text-sm mb-1">Due Date *</label><input type="date" id="i_dueDate" required class="dark-input"></div><div><label class="block text-sm mb-1">Status</label><select id="i_status" class="dark-input"><option>DRAFT</option><option>SENT</option><option>PAID</option></select></div><div><label class="block text-sm mb-1">Notes</label><textarea id="i_notes" class="dark-input"></textarea></div><hr><div><div class="flex justify-between mb-2"><h4 class="text-sm font-medium">Line Items</h4><button type="button" onclick="addInvoiceLineItem()" class="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded">+ Add</button></div><div id="invoice-items-container" class="space-y-2"></div></div><div class="mt-4 space-y-1 text-sm"><div class="flex justify-between"><span>Subtotal:</span><span id="inv_subtotal">AED 0.00</span></div><div class="flex justify-between"><span>VAT:</span><span id="inv_vat">AED 0.00</span></div><div class="flex justify-between font-bold border-t pt-1"><span>Total:</span><span id="inv_grand_total">AED 0.00</span></div></div>`); const mb = document.querySelector('#modal > div'); mb.classList.remove('max-w-md'); mb.classList.add('max-w-2xl'); document.getElementById('i_customerId').value = inv.customerId; document.getElementById('i_dueDate').value = inv.dueDate ? new Date(inv.dueDate).toISOString().split('T')[0] : ''; document.getElementById('i_status').value = inv.status; document.getElementById('i_notes').value = inv.notes || ''; if (inv.lineItems?.length) inv.lineItems.forEach(li => addInvoiceLineItem(li.description, li.quantity, li.unitPrice, li.vatRate)); else addInvoiceLineItem(inv.notes||'Service', 1, parseFloat(inv.subtotal), 5); modalForm.onsubmit = (e) => { e.preventDefault(); const items = collectInvoiceLineItems(); if (!items.length) { alert('Add at least 1 item.'); return; } const sub = items.reduce((s,i)=>s+(i.qty*i.unitPrice),0), vat = items.reduce((s,i)=>s+i.vatAmount,0), tot = sub+vat; apiFetch(`/invoices/${id}`,'PATCH',{customerId:getInput('i_customerId'),dueDate:getInput('i_dueDate'),subtotal:sub,vatAmount:vat,total:tot,status:getInput('i_status'),notes:getInput('i_notes'),lineItems:items}).then(()=>{closeModal();alert('Updated!');fetchAndRenderInvoices();}).catch(err=>{document.getElementById('modal-error').innerText=err.message;document.getElementById('modal-error').classList.remove('hidden');}); }; } catch (e) { alert('Failed'); } }

async function deleteInvoice(id) { if (confirm('Delete?')) { try { await apiFetch(`/invoices/${id}`, 'DELETE'); fetchAndRenderInvoices(); } catch (e) { alert('Failed'); } } }

async function viewInvoice(id) { try { const inv = await apiFetch(`/invoices/${id}`); const comp = await apiFetch('/company'); const mb = document.querySelector('#modal > div'); mb.classList.remove('max-w-md', 'max-w-3xl', 'max-w-sm'); mb.classList.add('max-w-5xl', 'p-0'); let liHtml = inv.lineItems?.length ? inv.lineItems.map((li,i)=>`<tr class="border-b"><td class="py-2 px-3 border-r">${i+1}</td><td class="py-2 px-3 border-r">${li.description}</td><td class="py-2 px-3 text-center border-r">${li.quantity}</td><td class="py-2 px-3 text-right border-r">${parseFloat(li.exclVAT||li.quantity*li.unitPrice).toFixed(2)}</td><td class="py-2 px-3 text-center border-r">${li.vatRate||5}%</td><td class="py-2 px-3 text-right border-r">${parseFloat(li.vatAmount||0).toFixed(2)}</td><td class="py-2 px-3 text-right">${parseFloat(li.inclVAT||((li.quantity*li.unitPrice)+(li.vatAmount||0))).toFixed(2)}</td></tr>`).join('') : `<tr class="border-b"><td class="py-2 px-3 border-r">1</td><td class="py-2 px-3 border-r">${inv.notes||'Service'}</td><td class="py-2 px-3 text-center border-r">1</td><td class="py-2 px-3 text-right border-r">${parseFloat(inv.subtotal||0).toFixed(2)}</td><td class="py-2 px-3 text-center border-r">5%</td><td class="py-2 px-3 text-right border-r">${parseFloat(inv.vatAmount||0).toFixed(2)}</td><td class="py-2 px-3 text-right">${parseFloat(inv.total||0).toFixed(2)}</td></tr>`; openModal('Invoice', `<div class="no-print sticky top-0 bg-slate-50 py-2 px-4 flex justify-end gap-2 border-b"><button onclick="window.print()" class="bg-gray-800 text-white px-4 py-2 rounded text-sm">Print</button><button onclick="downloadInvoicePDF('${inv.invoiceNumber}')" class="bg-blue-600 text-white px-4 py-2 rounded text-sm">PDF</button><button onclick="closeModal()" class="bg-red-500 text-white px-4 py-2 rounded text-sm">Close</button></div><div id="print-area" class="a4-page"><div class="a4-header"><div>${comp.invoiceHeader?`<img src="${comp.invoiceHeader}" class="h-20 mb-2">`:`<h1 class="text-2xl font-bold text-blue-800">${comp.name||'MAK INFRATECH'}</h1>`}<p class="text-sm text-gray-600">${comp.address||''}</p><p class="text-sm text-gray-600">TRN: ${comp.trn||'N/A'}</p></div><div class="text-right"><h2 class="text-2xl font-bold uppercase border-2 border-blue-800 text-blue-800 px-4 py-1 inline-block">TAX INVOICE</h2><p class="text-sm mt-2">No: ${inv.invoiceNumber}</p><p class="text-sm">Date: ${inv.issueDate?new Date(inv.issueDate).toLocaleDateString():'N/A'}</p><p class="text-sm">Due: ${inv.dueDate?new Date(inv.dueDate).toLocaleDateString():'N/A'}</p></div></div><div class="grid grid-cols-2 gap-8 mb-8 border-b pb-4"><div><div class="text-xs uppercase text-gray-500 mb-1">From</div><div class="font-bold">${comp.name||'N/A'}</div><div class="text-sm text-gray-600">TRN: ${comp.trn||'N/A'}</div></div><div class="text-right"><div class="text-xs uppercase text-gray-500 mb-1">Bill To</div><div class="font-bold">${inv.customer?.name||'N/A'}</div><div class="text-sm text-gray-600">TRN: ${inv.customer?.trn||'N/A'}</div></div></div><table class="w-full border-collapse mb-8 text-sm"><thead><tr class="bg-gray-100 border-b-2 border-gray-300"><th class="py-2 px-3 text-left border-r">#</th><th class="py-2 px-3 text-left border-r">Description</th><th class="py-2 px-3 text-center border-r">Qty</th><th class="py-2 px-3 text-right border-r">Excl VAT</th><th class="py-2 px-3 text-center border-r">VAT %</th><th class="py-2 px-3 text-right border-r">VAT Amt</th><th class="py-2 px-3 text-right">Incl VAT</th></tr></thead><tbody>${liHtml}</tbody></table><div class="flex justify-end mb-12"><div class="w-1/2 space-y-2"><div class="flex justify-between text-sm"><span>Excl VAT:</span><span>AED ${parseFloat(inv.subtotal||0).toFixed(2)}</span></div><div class="flex justify-between text-sm"><span>VAT:</span><span>AED ${parseFloat(inv.vatAmount||0).toFixed(2)}</span></div><div class="flex justify-between font-bold text-lg border-t-2 pt-2"><span>Total:</span><span>AED ${parseFloat(inv.total||0).toFixed(2)}</span></div></div></div><div class="a4-footer flex justify-between items-end"><div class="text-center">${comp.companySealUrl?`<img src="${comp.companySealUrl}" class="w-24 h-24 object-contain opacity-90">`:''}<span class="text-xs text-gray-500 mt-1 block">Seal</span></div><div class="text-center">${comp.authorizedSignatureUrl?`<img src="${comp.authorizedSignatureUrl}" class="h-16 object-contain">`:''}<div class="border-t border-gray-800 w-48 pt-1 text-sm">Signatory</div></div></div></div>`, true); } catch (e) { alert('Failed'); } }

function downloadInvoicePDF(in) { const el = document.getElementById('print-area'); html2pdf().set({margin:0,filename:`Invoice_${in}.pdf`,image:{type:'jpeg',quality:0.98},html2canvas:{scale:2,useCORS:true},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}}).from(el).save(); }

// ==================== INVOICE TEMPLATES ====================
function selectInvoiceTemplate(tpl) { selectedInvoiceTemplate = tpl; highlightSelectedTemplate(); }
function highlightSelectedTemplate() { document.querySelectorAll('.template-card').forEach(c => c.classList.remove('selected')); const el = document.getElementById(`tpl-${selectedInvoiceTemplate}`); if (el) el.classList.add('selected'); }
function saveInvoiceTemplate() { localStorage.setItem('invoice_template', selectedInvoiceTemplate); alert('Template saved!'); }

// ==================== PURCHASES ====================
async function fetchAndRenderPurchases() { const tbody = document.getElementById('tbody-purchases'); if (!tbody) return; tbody.innerHTML = `<tr><td colspan="5" class="p-6 text-center text-gray-500">Loading...</td></tr>`; try { const data = await apiFetch('/purchases'); if (data.length === 0) { tbody.innerHTML = `<tr><td colspan="5" class="p-6 text-center text-gray-500">No Purchases.</td></tr>`; return; } tbody.innerHTML = data.map(item => `<tr><td class="px-4 py-3 text-sm">${item.billNumber||'-'}</td><td class="px-4 py-3 text-sm">${item.supplierName||'-'}</td><td class="px-4 py-3 text-sm">${item.purchaseDate?new Date(item.purchaseDate).toLocaleDateString():'-'}</td><td class="px-4 py-3 text-sm">AED ${parseFloat(item.totalAmount||0).toFixed(2)}</td><td class="px-4 py-3"><span class="px-2 py-1 text-xs rounded-full ${item.paymentStatus==='PAID'?'bg-green-100 text-green-700':'bg-yellow-100 text-yellow-700'}">${item.paymentStatus||'UNPAID'}</span></td></tr>`).join(''); } catch (e) { tbody.innerHTML = `<tr><td colspan="5" class="p-6 text-center text-red-500">Failed.</td></tr>`; } }

function handleReceiptUpload(event) { const f = event.target.files[0]; if (!f) return; const r = new FileReader(); r.onload = (e) => { purchaseReceiptData = e.target.result; document.getElementById('receipt_preview').src = e.target.result; }; r.readAsDataURL(f); }

async function openPurchaseModal() { purchaseReceiptData = null; const wo = await fetchDropdown('/work-orders'); const ao = await fetchDropdown('/assets'); openModal('New Purchase', `<div class="grid grid-cols-2 gap-4"><div><label class="block text-sm mb-1">Supplier *</label><input type="text" id="pur_supplier" required class="dark-input"></div><div><label class="block text-sm mb-1">Bill No.</label><input type="text" id="pur_bill" class="dark-input"></div></div><div class="grid grid-cols-2 gap-4"><div><label class="block text-sm mb-1">Date</label><input type="date" id="pur_pdate" class="dark-input"></div><div><label class="block text-sm mb-1">Due</label><input type="date" id="pur_ddate" class="dark-input"></div></div><div class="grid grid-cols-2 gap-4"><div><label class="block text-sm mb-1">WO</label><select id="pur_woId" class="dark-input"><option value="">None</option>${wo}</select></div><div><label class="block text-sm mb-1">Asset</label><select id="pur_assetId" class="dark-input"><option value="">None</option>${ao}</select></div></div><div class="border-t pt-4 mt-4"><div class="flex justify-between mb-2"><h4 class="text-sm font-medium">Items</h4><button type="button" onclick="addPurchaseItemRow()" class="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded">+ Add</button></div><div id="pur_items_container" class="space-y-2"></div><div class="flex justify-end mt-4 text-sm"><div class="w-48 space-y-1"><div class="flex justify-between"><span>Subtotal:</span><span id="pur_subtotal">0.00</span></div><div class="flex justify-between"><span>VAT:</span><span id="pur_vat">0.00</span></div><div class="flex justify-between font-bold border-t pt-1"><span>Total:</span><span id="pur_total">0.00</span></div></div></div></div><div class="border-t pt-4 mt-4 grid grid-cols-2 gap-4"><div><label class="block text-sm mb-1">Pay Status</label><select id="pur_pstatus" class="dark-input"><option>UNPAID</option><option>PAID</option><option>PARTIAL</option></select></div><div><label class="block text-sm mb-1">Method</label><select id="pur_pmethod" class="dark-input"><option>CASH</option><option>CARD</option><option>BANK_TRANSFER</option></select></div></div>`); const mb = document.querySelector('#modal > div'); mb.classList.remove('max-w-md'); mb.classList.add('max-w-2xl'); addPurchaseItemRow(); document.getElementById('pur_pdate').valueAsDate = new Date(); modalForm.onsubmit = (e) => { e.preventDefault(); const items = []; document.querySelectorAll('.po-item-row').forEach(row => { const n = row.querySelector('.item-name').value, c = row.querySelector('.item-cat').value, q = parseFloat(row.querySelector('.item-qty').value)||0, p = parseFloat(row.querySelector('.item-price').value)||0, v = parseFloat(row.querySelector('.item-vat').value)||0, t = (q*p)+((q*p)*(v/100)); if (n) items.push({name:n,cat:c,qty:q,price:p,vat:v,total:t}); }); if (!items.length) { alert('Add 1 item.'); return; } const sub = items.reduce((s,i)=>s+(i.qty*i.price),0), va = items.reduce((s,i)=>s+((i.qty*i.price)*(i.vat/100)),0); handleSubmit('/purchases', {supplierName:getInput('pur_supplier'),billNumber:getInput('pur_bill'),purchaseDate:getInput('pur_pdate'),dueDate:getInput('pur_ddate'),workOrderId:getInput('pur_woId')||null,assetId:getInput('pur_assetId')||null,items,subtotal:sub,vatAmount:va,totalAmount:sub+va,paymentStatus:getInput('pur_pstatus'),paymentMethod:getInput('pur_pmethod'),receiptUrl:purchaseReceiptData}, 'Purchase saved!', {tableId:'tbody-purchases'}); }; }

function addPurchaseItemRow() { document.getElementById('pur_items_container').insertAdjacentHTML('beforeend', `<div class="po-item-row grid grid-cols-12 gap-2 items-center"><input type="text" placeholder="Name" class="item-name col-span-4 dark-input"><input type="text" placeholder="Cat" class="item-cat col-span-3 dark-input"><input type="number" placeholder="Qty" step="0.01" class="item-qty col-span-2 dark-input" oninput="updatePurchaseTotals()"><input type="number" placeholder="Price" step="0.01" class="item-price col-span-3 dark-input" oninput="updatePurchaseTotals()"><input type="number" placeholder="VAT%" step="0.01" value="5" class="item-vat col-span-2 dark-input" oninput="updatePurchaseTotals()"><span class="col-span-2 text-right text-sm item-total">0.00</span><button type="button" onclick="this.parentElement.remove();updatePurchaseTotals();" class="col-span-1 text-red-500">X</button></div>`); updatePurchaseTotals(); }
function updatePurchaseTotals() { let s=0,v=0; document.querySelectorAll('.po-item-row').forEach(row => { const q=parseFloat(row.querySelector('.item-qty').value)||0, p=parseFloat(row.querySelector('.item-price').value)||0, vat=parseFloat(row.querySelector('.item-vat').value)||0, rt=(q*p)+((q*p)*(vat/100)); row.querySelector('.item-total').innerText=rt.toFixed(2); s+=(q*p); v+=((q*p)*(vat/100)); }); document.getElementById('pur_subtotal').innerText=s.toFixed(2); document.getElementById('pur_vat').innerText=v.toFixed(2); document.getElementById('pur_total').innerText=(s+v).toFixed(2); }

// ==================== USERS ====================
async function fetchAndRenderUsers() { const tbody = document.getElementById('tbody-users'); if (!tbody) return; tbody.innerHTML = `<tr><td colspan="4" class="p-6 text-center text-gray-500">Loading...</td></tr>`; try { const data = await apiFetch('/users'); if (data.length === 0) { tbody.innerHTML = `<tr><td colspan="4" class="p-6 text-center text-gray-500">No Users.</td></tr>`; return; } tbody.innerHTML = data.map(item => `<tr><td class="px-4 py-3 text-sm">${item.name}</td><td class="px-4 py-3 text-sm">${item.email}</td><td class="px-4 py-3 text-sm">${item.role}</td><td class="px-4 py-3 text-sm flex gap-2"><button onclick="editUser('${item.id}')" class="text-blue-600 px-1">Edit</button><button onclick="deleteUser('${item.id}')" class="text-red-600 px-1">Del</button></td></tr>`).join(''); } catch (e) { tbody.innerHTML = `<tr><td colspan="4" class="p-6 text-center text-red-500">Failed.</td></tr>`; } }

async function openUserModal() { openModal('New User', `<div><label class="block text-sm mb-1">Name</label><input type="text" id="u_name" required class="dark-input"></div><div><label class="block text-sm mb-1">Email</label><input type="email" id="u_email" required class="dark-input"></div><div><label class="block text-sm mb-1">Password</label><input type="password" id="u_password" required class="dark-input"></div><div><label class="block text-sm mb-1">Role</label><select id="u_role" class="dark-input"><option>SUPER_ADMIN</option><option>ADMIN</option><option>MANAGER</option><option>COORDINATOR</option><option selected>TECHNICIAN</option><option>ACCOUNTANT</option><option>VIEWER</option></select></div>`); modalForm.onsubmit = (e) => { e.preventDefault(); handleSubmit('/users', {name:getInput('u_name'),email:getInput('u_email'),password:getInput('u_password'),role:getInput('u_role')}, 'User created!', {tableId:'tbody-users'}); }; }

async function editUser(id) { try { const u = await apiFetch(`/users/${id}`); openModal('Edit User', `<div><label class="block text-sm mb-1">Name</label><input type="text" id="u_name" required value="${u.name}" class="dark-input"></div><div><label class="block text-sm mb-1">Email</label><input type="email" id="u_email" required value="${u.email}" class="dark-input"></div><div><label class="block text-sm mb-1">New Password</label><input type="password" id="u_password" class="dark-input"></div><div><label class="block text-sm mb-1">Role</label><select id="u_role" class="dark-input"><option value="SUPER_ADMIN" ${u.role==='SUPER_ADMIN'?'selected':''}>SUPER_ADMIN</option><option value="ADMIN" ${u.role==='ADMIN'?'selected':''}>ADMIN</option><option value="MANAGER" ${u.role==='MANAGER'?'selected':''}>MANAGER</option><option value="COORDINATOR" ${u.role==='COORDINATOR'?'selected':''}>COORDINATOR</option><option value="TECHNICIAN" ${u.role==='TECHNICIAN'?'selected':''}>TECHNICIAN</option><option value="ACCOUNTANT" ${u.role==='ACCOUNTANT'?'selected':''}>ACCOUNTANT</option><option value="VIEWER" ${u.role==='VIEWER'?'selected':''}>VIEWER</option></select></div>`); modalForm.onsubmit = async (e) => { e.preventDefault(); const data = {name:getInput('u_name'),email:getInput('u_email'),role:getInput('u_role')}; if (getInput('u_password')) data.password = getInput('u_password'); try { await apiFetch(`/users/${id}`,'PATCH',data); closeModal(); alert('Updated!'); fetchAndRenderUsers(); } catch (err) { document.getElementById('modal-error').innerText = err.message; document.getElementById('modal-error').classList.remove('hidden'); } }; } catch (e) { alert('Failed'); } }

async function deleteUser(id) { if (confirm('Delete?')) { try { await apiFetch(`/users/${id}`,'DELETE'); fetchAndRenderUsers(); } catch (e) { alert('Failed'); } } }

// ==================== REPORTS ====================
async function loadReports() { try { const d = await apiFetch('/reports/summary'); const fn = n => parseFloat(n).toFixed(2); document.getElementById('rep-revenue').innerText = `AED ${fn(d.revenue.total)}`; document.getElementById('rep-collected').innerText = `AED ${fn(d.revenue.paid)}`; document.getElementById('rep-expenses').innerText = `AED ${fn(d.expenses.total)}`; document.getElementById('rep-profit').innerText = `AED ${fn(d.netProfit)}`; let wh = ''; if (d.workOrders?.length) { d.workOrders.forEach(s => { let c = 'bg-gray-100 text-gray-700'; if (s.status==='COMPLETED') c='bg-green-100 text-green-700'; if (s.status==='IN_PROGRESS') c='bg-blue-100 text-blue-700'; if (s.status==='PENDING') c='bg-yellow-100 text-yellow-700'; wh += `<span class="px-4 py-2 rounded-lg text-sm ${c}">${s.status.replace('_',' ')}: ${s._count.status}</span>`; }); } else { wh = '<span class="text-gray-500">None.</span>'; } document.getElementById('rep-wo-stats').innerHTML = wh; } catch (e) { console.error('Failed',e); } }

