function handleImageUpload(event, fn, pid) { const f = event.target.files[0]; if (!f) return; const r = new FileReader(); r.onload = (e) => { companyImageData[fn] = e.target.result; document.getElementById(pid).src = e.target.result; }; r.readAsDataURL(f); }

async function loadCompanySettings() { try { const d = await apiFetch('/company'); document.getElementById('set_name').value = d.name||''; document.getElementById('set_trn').value = d.trn||''; document.getElementById('set_phone').value = d.phone||''; document.getElementById('set_email').value = d.email||''; document.getElementById('set_address').value = d.address||''; document.getElementById('set_vat').value = d.vatPercent||5; document.getElementById('set_invPrefix').value = d.invoicePrefix||'INV-'; document.getElementById('set_poPrefix').value = d.poPrefix||'PO-'; document.getElementById('set_woPrefix').value = d.woPrefix||'WO-'; ['logo','header','footer','sig','seal'].forEach(k => { const el = document.getElementById(`img-preview-${k}`); if (d[`${k}Url`]) el.src = d[`${k}Url`]; }); } catch (e) {} }

async function saveCompanySettings() { const d = {name:document.getElementById('set_name').value,trn:document.getElementById('set_trn').value,phone:document.getElementById('set_phone').value,email:document.getElementById('set_email').value,address:document.getElementById('set_address').value,vatPercent:document.getElementById('set_vat').value,invoicePrefix:document.getElementById('set_invPrefix').value,poPrefix:document.getElementById('set_poPrefix').value,woPrefix:document.getElementById('set_woPrefix').value}; try { await apiFetch('/company','POST',d); alert('Saved!'); } catch (e) { alert('Failed: '+e.message); } }

async function loadSystemSettings() { try { const d = await apiFetch('/settings'); document.getElementById('set_sysName').value = d.systemName||''; document.getElementById('set_currency').value = d.currency||'AED'; document.getElementById('set_timezone').value = d.timezone||'Asia/Dubai'; document.getElementById('set_lowStock').value = d.lowStockThreshold||5; document.getElementById('set_emailNotif').checked = d.enableEmailNotifications; document.getElementById('set_smsNotif').checked = d.enableSMSNotifications; } catch (e) {} }

async function saveSystemSettings() { const d = {systemName:document.getElementById('set_sysName').value,currency:document.getElementById('set_currency').value,timezone:document.getElementById('set_timezone').value,lowStockThreshold:parseInt(document.getElementById('set_lowStock').value),enableEmailNotifications:document.getElementById('set_emailNotif').checked,enableSMSNotifications:document.getElementById('set_smsNotif').checked}; try { await apiFetch('/settings','POST',d); alert('Saved!'); } catch (e) { alert('Failed: '+e.message); } }

// ==================== STAFF ====================
function handleStaffPhotoUpload(event) { const f = event.target.files[0]; if (!f) return; const r = new FileReader(); r.onload = (e) => { staffPhotoData = e.target.result; document.getElementById('staff_photo_preview').src = e.target.result; }; r.readAsDataURL(f); }

async function fetchAndRenderStaff() { const tbody = document.getElementById('tbody-staff'); if (!tbody) return; tbody.innerHTML = `<tr><td colspan="7" class="p-6 text-center text-gray-500">Loading...</td></tr>`; try { const data = await apiFetch('/staff'); if (data.length === 0) { tbody.innerHTML = `<tr><td colspan="7" class="p-6 text-center text-gray-500">No Staff.</td></tr>`; return; } tbody.innerHTML = ''; data.forEach(item => { const tr = document.createElement('tr'); tr.className = "cursor-pointer hover:bg-blue-50"; tr.onclick = () => viewStaffDocument(item.id); tr.innerHTML = `<td class="px-4 py-3">${item.photoUrl?`<img src="${item.photoUrl}" class="w-10 h-10 rounded-full object-cover">`:'<div class="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center text-gray-500">N/A</div>'}</td><td class="px-4 py-3 text-sm">${item.firstName} ${item.lastName}</td><td class="px-4 py-3 text-sm">${item.jobTitle||'-'}</td><td class="px-4 py-3 text-sm">${item.nationality||'-'}</td><td class="px-4 py-3 text-sm">${item.phone||'-'}</td><td class="px-4 py-3 text-sm">${item.passportExpiry?new Date(item.passportExpiry).toLocaleDateString():'-'}</td><td class="px-4 py-3 text-sm">${item.emiratesIdExpiry?new Date(item.emiratesIdExpiry).toLocaleDateString():'-'}</td>`; tbody.appendChild(tr); }); } catch (e) { tbody.innerHTML = `<tr><td colspan="7" class="p-6 text-center text-red-500">Failed.</td></tr>`; } }

async function viewStaffDocument(id) { try { const s = await apiFetch(`/staff/${id}`); const c = await apiFetch('/company'); const mb = document.querySelector('#modal > div'); mb.classList.remove('max-w-md','max-w-2xl','max-w-sm'); mb.classList.add('max-w-5xl','p-0'); openModal('Staff Document', `<div class="no-print sticky top-0 bg-slate-50 py-2 px-4 flex justify-end gap-2 border-b"><button onclick="window.print()" class="bg-gray-800 text-white px-4 py-2 rounded text-sm">Print</button><button onclick="downloadStaffPDF('${s.id}')" class="bg-blue-600 text-white px-4 py-2 rounded text-sm">PDF</button><button onclick="closeModal()" class="bg-red-500 text-white px-4 py-2 rounded text-sm">Close</button></div><div id="print-area" class="a4-page"><div class="a4-header"><div>${c.logoUrl?`<img src="${c.logoUrl}" class="h-16 mb-2">`:'<h1 class="text-2xl font-bold text-blue-800">MAK INFRATECH</h1>'}<p class="text-sm text-gray-600">${c.address||''}</p><p class="text-sm text-gray-600">TRN: ${c.trn||'N/A'}</p></div><div class="text-right"><h2 class="text-xl font-bold uppercase">Staff Record</h2></div></div><div class="grid grid-cols-3 gap-6 mb-8"><div class="text-center">${s.photoUrl?`<img src="${s.photoUrl}" class="w-40 h-48 object-cover mx-auto border">`:'<div class="w-40 h-48 bg-gray-100 mx-auto flex items-center justify-center text-gray-400 border">No Photo</div>'}</div><div class="col-span-2 space-y-3 text-sm"><div><strong>ID:</strong> ${s.id.substring(0,8).toUpperCase()}</div><div><strong>Name:</strong> ${s.firstName} ${s.lastName}</div><div><strong>Job:</strong> ${s.jobTitle||'N/A'}</div><div><strong>Phone:</strong> ${s.phone||'N/A'}</div><div><strong>Passport:</strong> ${s.passportNumber||'N/A'} (${s.passportExpiry?new Date(s.passportExpiry).toLocaleDateString():'N/A'})</div><div><strong>Visa:</strong> ${s.visaNumber||'N/A'} (${s.visaExpiry?new Date(s.visaExpiry).toLocaleDateString():'N/A'})</div><div><strong>EID:</strong> ${s.emiratesId||'N/A'} (${s.emiratesIdExpiry?new Date(s.emiratesIdExpiry).toLocaleDateString():'N/A'})</div><div><strong>Insurance:</strong> ${s.insuranceProvider||'N/A'} - ${s.insurancePolicyNumber||'N/A'}</div></div></div></div>`, true); } catch (e) { alert('Failed'); } }

function downloadStaffPDF(id) { const el = document.getElementById('print-area'); html2pdf().set({margin:0,filename:`Staff_${id.substring(0,8)}.pdf`,image:{type:'jpeg',quality:0.98},html2canvas:{scale:2,useCORS:true},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}}).from(el).save(); }

async function openStaffModal() { staffPhotoData = null; openModal('New Staff', `<div class="flex flex-col items-center mb-4"><img id="staff_photo_preview" src="https://via.placeholder.com/100?text=Photo" class="w-24 h-24 rounded-full object-cover border-2 border-gray-200 mb-2"><input type="file" accept="image/*" onchange="handleStaffPhotoUpload(event)" class="text-sm"></div><div class="grid grid-cols-2 gap-4"><div><label class="block text-sm mb-1">First Name</label><input type="text" id="st_fname" required class="dark-input"></div><div><label class="block text-sm mb-1">Last Name</label><input type="text" id="st_lname" required class="dark-input"></div></div><div class="grid grid-cols-2 gap-4"><div><label class="block text-sm mb-1">Job Title</label><input type="text" id="st_job" class="dark-input"></div><div><label class="block text-sm mb-1">Phone</label><input type="text" id="st_phone" class="dark-input"></div></div><div><label class="block text-sm mb-1">Nationality</label><select id="st_nat" class="dark-input"><option>UAE</option><option>India</option><option>Pakistan</option><option>Philippines</option><option>Egypt</option><option>Other</option></select></div><div class="grid grid-cols-2 gap-4"><div><label class="block text-sm mb-1">Passport</label><input type="text" id="st_pp" class="dark-input"></div><div><label class="block text-sm mb-1">PP Expiry</label><input type="date" id="st_ppExp" class="dark-input"></div></div><div class="grid grid-cols-2 gap-4"><div><label class="block text-sm mb-1">EID</label><input type="text" id="st_eid" class="dark-input"></div><div><label class="block text-sm mb-1">EID Expiry</label><input type="date" id="st_eidExp" class="dark-input"></div></div><div class="grid grid-cols-2 gap-4"><div><label class="block text-sm mb-1">Visa</label><input type="text" id="st_visa" class="dark-input"></div><div><label class="block text-sm mb-1">Visa Expiry</label><input type="date" id="st_visaExp" class="dark-input"></div></div>`); modalForm.onsubmit = (e) => { e.preventDefault(); handleSubmit('/staff', {firstName:getInput('st_fname'),lastName:getInput('st_lname'),photoUrl:staffPhotoData,jobTitle:getInput('st_job'),phone:getInput('st_phone'),nationality:getInput('st_nat'),passportNumber:getInput('st_pp'),passportExpiry:getInput('st_ppExp'),emiratesId:getInput('st_eid'),emiratesIdExpiry:getInput('st_eidExp'),visaNumber:getInput('st_visa'),visaExpiry:getInput('st_visaExp')}, 'Staff added!', {tableId:'tbody-staff'}); }; }

// ==================== FORM MODALS ====================
async function openCustomerModal() { openModal('New Customer', `<div><label class="block text-sm mb-1">Name</label><input type="text" id="c_name" required class="dark-input"></div><div><label class="block text-sm mb-1">Phone</label><input type="text" id="c_phone" class="dark-input"></div><div><label class="block text-sm mb-1">Email</label><input type="email" id="c_email" class="dark-input"></div><div><label class="block text-sm mb-1">Address</label><input type="text" id="c_address" class="dark-input"></div>`); modalForm.onsubmit = (e) => { e.preventDefault(); handleSubmit('/customers', {name:getInput('c_name'),phone:getInput('c_phone'),email:getInput('c_email'),address:getInput('c_address')}, 'Customer created!', {endpoint:'/customers',tableId:'tbody-customers',columns:['name','phone','email','address']}); }; }
async function openBuildingModal() { const co = await fetchDropdown('/customers'); openModal('New Building', `<div><label class="block text-sm mb-1">Customer</label><select id="b_customerId" class="dark-input"><option value="">Select</option>${co}</select></div><div><label class="block text-sm mb-1">Name</label><input type="text" id="b_name" required class="dark-input"></div><div><label class="block text-sm mb-1">Address</label><input type="text" id="b_address" class="dark-input"></div><div><label class="block text-sm mb-1">City</label><input type="text" id="b_city" class="dark-input"></div><div><label class="block text-sm mb-1">Emirate</label><input type="text" id="b_emirate" class="dark-input"></div>`); modalForm.onsubmit = (e) => { e.preventDefault(); handleSubmit('/buildings', {customerId:getInput('b_customerId'),name:getInput('b_name'),address:getInput('b_address'),city:getInput('b_city'),emirate:getInput('b_emirate')}, 'Building created!', {endpoint:'/buildings',tableId:'tbody-buildings',columns:['name','city','emirate']}); }; }
async function openAmcModal() { const co = await fetchDropdown('/customers'); openModal('New AMC', `<div><label class="block text-sm mb-1">Customer</label><select id="a_customerId" required class="dark-input"><option value="">Select</option>${co}</select></div><div><label class="block text-sm mb-1">Contract No.</label><input type="text" id="a_contractNumber" required class="dark-input"></div><div class="grid grid-cols-2 gap-4"><div><label class="block text-sm mb-1">Start</label><input type="date" id="a_startDate" required class="dark-input"></div><div><label class="block text-sm mb-1">End</label><input type="date" id="a_endDate" required class="dark-input"></div></div><div><label class="block text-sm mb-1">Value (AED)</label><input type="number" id="a_value" required class="dark-input"></div><div><label class="block text-sm mb-1">PPM Freq (Months)</label><input type="number" id="a_ppmFrequency" value="3" required class="dark-input"></div><div><label class="block text-sm mb-1">Payment Type</label><select id="a_paymentType" onchange="toggleEmiField()" class="dark-input"><option>LUMPSUM</option><option>EMI</option></select></div><div id="emiCountDiv" style="display:none;"><label class="block text-sm mb-1">EMI Count</label><input type="number" id="a_emiCount" value="0" class="dark-input"></div>`); document.getElementById('a_startDate').valueAsDate = new Date(); let ny = new Date(); ny.setFullYear(ny.getFullYear()+1); document.getElementById('a_endDate').valueAsDate = ny; modalForm.onsubmit = (e) => { e.preventDefault(); handleSubmit('/amc', {customerId:getInput('a_customerId'),contractNumber:getInput('a_contractNumber'),startDate:getInput('a_startDate'),endDate:getInput('a_endDate'),value:parseFloat(getInput('a_value')),ppmFrequency:parseInt(getInput('a_ppmFrequency')),paymentType:getInput('a_paymentType'),emiCount:parseInt(getInput('a_emiCount'))||0}, 'AMC created!', {endpoint:'/amc',tableId:'tbody-amc',columns:['contractNumber','value','status']}); }; }
function toggleEmiField() { document.getElementById('emiCountDiv').style.display = document.getElementById('a_paymentType').value === 'EMI' ? 'block' : 'none'; }
async function openExpenseModal() { openModal('New Expense', `<div><label class="block text-sm mb-1">Category</label><input type="text" id="e_category" required class="dark-input"></div><div><label class="block text-sm mb-1">Amount (AED)</label><input type="number" id="e_amount" required class="dark-input"></div><div><label class="block text-sm mb-1">Description</label><textarea id="e_description" class="dark-input"></textarea></div>`); modalForm.onsubmit = (e) => { e.preventDefault(); handleSubmit('/expenses', {category:getInput('e_category'),amount:parseFloat(getInput('e_amount')),description:getInput('e_description')}, 'Expense created!', {endpoint:'/expenses',tableId:'tbody-expenses',columns:['category','amount','status']}); }; }

async function openPoModal() { 
    openModal('New PO', `<div><label class="block text-sm mb-1">PO Number</label><input type="text" id="p_poNumber" required class="dark-input"></div><div><label class="block text-sm mb-1">Supplier</label><input type="text" id="p_supplierName" required class="dark-input"></div><div><label class="block text-sm mb-1">Phone</label><input type="text" id="p_supplierPhone" class="dark-input"></div><div><label class="block text-sm mb-1">Total (AED)</label><input type="number" id="p_total" required class="dark-input"></div>`); 
    modalForm.onsubmit = (e) => { 
        e.preventDefault(); 
        const t = parseFloat(getInput('p_total')); 
        handleSubmit('/po', {poNumber:getInput('p_poNumber'),supplierName:getInput('p_supplierName'),supplierPhone:getInput('p_supplierPhone'),subtotal:t,vatAmount:t*0.05,total:t+(t*0.05)}, 'PO created!', {endpoint:'/po',tableId:'tbody-po',columns:['poNumber','supplierName','total']}); 
    }; 
}
